// project の数値 ID を抽出して前の since 情報と一緒に下流に渡す
const proj = $input.first().json;
if (!proj || proj.id == null) {
  throw new Error('Backlog get project failed: ' + JSON.stringify(proj).substring(0, 500));
}
const since = $('BigQuery: Get updated_since').first().json.updated_since;
return [{ json: { project_id: proj.id, updated_since: since } }];

// comments response の各 item に issueId が含まれるので、それで grouping して issue と紐付け
// status_changed_at は changeLog から status 変更分の最新を抽出
// last_comment_at = 各 issue の comments の最大 created
const now = new Date().toISOString();
const issuesAll = $('Backlog API: issues (paginated)').all();

const lastCommentByIssue = new Map();
const lastStatusChangeByIssue = new Map();
for (const item of $input.all()) {
  const body = item.json;
  const list = Array.isArray(body) ? body : (body && body.id != null ? [body] : []);
  for (const c of list) {
    if (!c || c.issueId == null) continue;
    const iid = String(c.issueId);
    if (c.created) {
      const prev = lastCommentByIssue.get(iid);
      if (!prev || c.created > prev) lastCommentByIssue.set(iid, c.created);
    }
    if (Array.isArray(c.changeLog)) {
      const isStatusChange = c.changeLog.some(cl => cl.field === 'status');
      if (isStatusChange && c.created) {
        const prev = lastStatusChangeByIssue.get(iid);
        if (!prev || c.created > prev) lastStatusChangeByIssue.set(iid, c.created);
      }
    }
  }
}

const rows = [];
for (const item of issuesAll) {
  const i = item.json;
  if (!i || i.id == null) continue;
  const iid = String(i.id);
  rows.push({
    issue_id:          iid,
    project_id:        i.projectId != null ? String(i.projectId) : null,
    issue_type:        i.issueType ? i.issueType.name : null,
    title:             i.summary || null,
    description:       (i.description || '').toString().substring(0, 50000) || null,
    status:            i.status ? i.status.name : null,
    priority:          i.priority ? i.priority.name : null,
    assignee:          i.assignee ? i.assignee.name : null,
    due_date:          i.dueDate ? String(i.dueDate).substring(0, 10) : null,
    created_at:        i.created || null,
    updated_at:        i.updated || null,
    resolved_at:       i.resolvedAt || null,
    status_changed_at: lastStatusChangeByIssue.get(iid) || null,
    last_comment_at:   lastCommentByIssue.get(iid) || null,
    inserted_at:       now
  });
}
return rows.map(json => ({ json }));

// comments response の各 item に issueId と projectId が含まれているので、直接利用 (index 依存しない)
const now = new Date().toISOString();
const out = [];
for (const item of $input.all()) {
  const body = item.json;
  const list = Array.isArray(body) ? body : (body && body.id != null ? [body] : []);
  for (const c of list) {
    if (!c || c.id == null || c.issueId == null) continue;
    out.push({
      comment_id:  String(c.id),
      issue_id:    String(c.issueId),
      project_id:  c.projectId != null ? String(c.projectId) : null,
      author:      (c.createdUser && c.createdUser.name) || null,
      content:     (c.content || '').toString().substring(0, 50000),
      created_at:  c.created || null,
      updated_at:  c.updated || null,
      inserted_at: now
    });
  }
}
return out.map(json => ({ json }));
